$f = [System.IO.File]::ReadAllText("Services/MainServices/RequestService.cs")\n$lines = $f -split "\r?\n"\n\n$insertIdx = -1\nfor ($i = 0; $i -lt $lines.Length; $i++) {\n    if ($lines[$i].Trim() -eq "isreqExist.ApprovalStatus = status;") {\n        $insertIdx = $i\n        break\n    }\n}\n\nif ($insertIdx -eq -1) {\n    Write-Host "Could not find insertion point"\n    exit 1\n}\n\nWrite-Host "Found at line $($insertIdx + 1)"\n\n$newLines = @(\n    "",\n    "                // Trigger 3: Release driver/vehicle on Denied or Cancelled",\n    '                if (status == "Denied" || status == "Cancelled")',\n    "                {",\n                    '                    var dispatch = await dbContext.DispatchDetails',\n                    '                        .Include(d => d.Driver)',\n                    '                        .Include(d => d.Vehicle)',\n                    '                        .FirstOrDefaultAsync(d => d.TicketId == id);',\n    "",\n                    '                    if (dispatch != null)',\n                    "                    {",\n                        '                        if (dispatch.Driver != null)',\n                        "                        {",\n                            '                            dispatch.Driver.Status = "Active";',\n                        "                        }",\n                        '                        if (dispatch.Vehicle != null)',\n                        "                        {",\n                            '                            dispatch.Vehicle.Status = "Available";',\n                        "                        }",\n                        '                        dispatch.VehicleStatus = "Released";',\n                    "                    }",\n                "                }"\n)\n\n$before = $lines[0..$insertIdx]\n$after = $lines[($insertIdx + 1)..($lines.Length - 1)]\n$allLines = $before + $newLines + $after\n$newContent = $allLines -join "\n"\n[System.IO.File]::WriteAllText("Services/MainServices/RequestService.cs", $newContent)\nWrite-Host "Done - Trigger 3 added"
